import requests
import json

url = "https://partner.shopeemobile.com/api/v2/principal/get_clip_video_performance?access_token=access_token&partner_id=partner_id&principal_id=principal_id&sign=sign&timestamp=timestamp"

payload=json.dumps({
  "cursor": 100,
  "end_date": "2026-01-31",
  "granularity": "month",
  "page_size": 100,
  "start_date": "2026-01-01",
  "timezone": "GMT+8",
  "video_list": [
    {
      "currency": "LOCAL",
      "shop_id": 181050132,
      "video_ids": [
        1453493,
        1453494
      ]
    }
  ]
})
headers = {
  'Content-Type': 'application/json'
}
response = requests.RPCRequest("POST",url,headers=headers, data=payload, allow_redirects=False)

print(response.text)

